const body = $input.first().json.body;

return {
  json: {
    articleId: body.articleId,
    title: body.title,
    keyPoints: body.keyPoints,
    createdAt: new Date().toISOString()
  }
};

// Fetch Hub Context Node
const articleId = $input.first().json.articleId;

if (!articleId) {
  throw new Error('Article ID is required to fetch Hub context');
}

const NOTION_TOKEN = process.env.NOTION_API_TOKEN;
const HUB_DB_ID = '2a268d5c-2986-813c-a8e5-eba390fb71fd';

const searchPayload = {
  filter: {
    property: 'Article ID',
    rich_text: {
      equals: articleId
    }
  }
};

try {
  const response = await $http.post(
    `https://api.notion.com/v1/databases/${HUB_DB_ID}/query`,
    {
      headers: {
        'Authorization': `Bearer ${NOTION_TOKEN}`,
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json'
      },
      body: searchPayload
    }
  );

  let hubPageId;
  let isNewEntry = false;
  let existingStatus = 'Draft';

  if (!response.results || response.results.length === 0) {
    // 新規作成
    const createPayload = {
      parent: { database_id: HUB_DB_ID },
      properties: {
        'Title': {
          title: [{
            text: {
              content: $input.first().json.title || `Article ${articleId}`
            }
          }]
        },
        'Article ID': {
          rich_text: [{
            text: {
              content: articleId
            }
          }]
        },
        'Workflow Status': {
          select: {
            name: 'Draft'
          }
        },
        'Created At': {
          date: {
            start: new Date().toISOString()
          }
        }
      }
    };

    const createResponse = await $http.post(
      'https://api.notion.com/v1/pages',
      {
        headers: {
          'Authorization': `Bearer ${NOTION_TOKEN}`,
          'Notion-Version': '2022-06-28',
          'Content-Type': 'application/json'
        },
        body: createPayload
      }
    );

    hubPageId = createResponse.id;
    isNewEntry = true;
  } else {
    hubPageId = response.results[0].id;
    existingStatus = response.results[0].properties['Workflow Status']?.select?.name || 'Draft';
  }

  return {
    json: {
      ...($input.first().json),
      hubContext: {
        hubPageId,
        articleId,
        isNewEntry,
        existingStatus
      }
    }
  };
} catch (error) {
  throw new Error(`Hub context fetch failed: ${error.message}`);
}

const data = $input.first().json;

const payload = {
  model: 'gpt-4o-mini',
  messages: [
    {
      role: 'system',
      content: 'あなたは縦型ショート動画の台本作成の専門家です。30-45秒の動画スクリプトをJSON形式で生成してください。'
    },
    {
      role: 'user',
      content: `以下のnote記事情報から動画スクリプトを生成してください。

記事タイトル: ${data.title}
キーポイント: ${data.keyPoints.join(', ')}

要件:
- 4セクション構成:Hook(0-10秒)/Pain(10-20秒)/Solution(20-35秒)/CTA(35-45秒)
- 各セクションに、テロップ文、読み上げ文、アセットタグを含める

JSON形式で出力してください`
    }
  ],
  temperature: 0.7,
  response_format: { type: 'json_object' }
};

return {
  json: {
    originalData: data,
    gptPayload: payload
  }
};

const response = $input.first().json.choices[0].message.content;
const scriptData = JSON.parse(response);

const payloadNode = $('GPTペイロード作成').first().json;
const inputData = payloadNode.originalData;

const assetTags = scriptData.segments ? scriptData.segments.map(s => s.assetTag).filter(Boolean) : [];

return {
  json: {
    articleId: inputData.articleId,
    title: inputData.title,
    scriptData,
    assetTags,
    createdAt: inputData.createdAt,
    hubContext: inputData.hubContext
  }
};

// Update Hub Status Node
const data = $input.first().json;
const hubContext = data.hubContext;

if (!hubContext || !hubContext.hubPageId) {
  throw new Error('Hub context is missing');
}

const scriptUrl = `https://n8n-python-production-344b.up.railway.app/webhook/wf7-video-script?articleId=${data.articleId}`;

const updatePayload = {
  properties: {
    'Workflow Status': {
      select: {
        name: 'ScriptReady'
      }
    },
    'Script JSON': {
      url: scriptUrl
    },
    'Latest Execution ID': {
      rich_text: [{
        text: {
          content: $execution.id || 'manual-' + Date.now()
        }
      }]
    },
    'Updated At': {
      date: {
        start: new Date().toISOString()
      }
    }
  }
};

return {
  json: {
    hubPageId: hubContext.hubPageId,
    updatePayload,
    scriptData: data.scriptData,
    articleId: data.articleId,
    title: data.title
  }
};

const notionResponse = $input.first().json;
const updateHubNode = $('Update Hub Status').first().json;

const scriptJson = {
  articleId: updateHubNode.articleId,
  version: '1.0',
  createdAt: new Date().toISOString(),
  ...updateHubNode.scriptData
};

return {
  json: {
    articleId: updateHubNode.articleId,
    title: updateHubNode.title,
    hubPageId: updateHubNode.hubPageId,
    hubPageUrl: notionResponse.url,
    scriptJson,
    status: 'ScriptReady'
  }
};
